/* РВ-6 · «ручна перевірка на опублікованій сторінці» (§6 ЗАВДАННЯ) — машиною: ЗІБРАНИЙ
   index.html з кореня репозиторію у справжньому Chromium, справжній Pyodide (з диска) і
   справжній `bridge` у ньому; модель — сценарна заглушка, яка відповідає ЗА СХЕМАМИ
   протоколу (ПАКЕТ_V1 → ОБРАЗИ_V1, ВЕРДИКТ_V1 → ОБРАЗИ_V1, ВИБІР_V1, ОПИС_ВІДПОВІДЬ_V1) і
   прозою рукам 3–4. Живих викликів моделі нема. Міряє рівно §6: чат заповнює плитки; рядок
   підтвердження випадку; чотири картки; промпти між ітераціями — JSON; у картці нема id/hex/
   номерів; журнал TSV має нові колонки. За зразком `рв3_стенд_чат.js` (РВ-3).

   v4.1 (19.09.2026): стенд СПЕРШУ ПРОХОДИТЬ ЗНАЙОМСТВО — три кроки нитки
   кнопками «Далі»/«Готово», як жінка. Доти він одразу ліз у `екран(2)`, лишався
   в `РЕЖИМ = 'старт'` і міряв чат над каналом помічниці, який паспорта не пише
   (БЕКЛОГ рядок 26; підтверджено живим прогоном, а не аналізом коду).

   v5 (19.09.2026, рядки 63 і 66 дошки): ШЛЯХ СТЕНДА ПОВТОРЮЄ ШЛЯХ ЖІНКИ У v5 —
   знайомство трьома кроками → екран сценарію з АРКУШЕМ ЛИСТА → розмова → КАРТКА
   СЦЕНАРІЮ в стрічці → рядок «Палітра» (окремий екран, чипи основ) → «Зібрати
   образи» У КАРТЦІ (`#зб-зібрати`) → картки. Доти стенд на екрані сценарію тиснув
   `#н-далі` — кнопку панелі знайомства, яку v5 тут ховає, — і падав на `element is
   not visible` (`page.click: Timeout 30000ms exceeded`), не дійшовши до жодної
   звірки збирання: у CI крок «стенд» давав 0 звірок. Дві звірки про текст екрана
   міряли слова v4 («після Готово — на екрані сценарію», «рядок „Я зрозуміла так“»)
   і червоніли на кожному прогоні; вони переписані на текст v5, узятий з
   `показ.html`, і не послаблені. Додано сцену 1б: екран «Палітра» — рекомендовані
   основи, збіг «нейтралі» з C*, чипи купно по сім'ях.

   Запуск (мережа не потрібна, крім одноразового наповнення кеша Pyodide):
     sh аудит/проби/стенд_pyodide_кеш.sh /tmp/pyodide          # один раз
     cd джерела && LYUSTERKO_CATALOG=повний python3 build_артефакт.py . /tmp/стенд/index.html показ-повний
     CHROMIUM=/opt/pw-browsers/chromium NODE_PATH=<тека з playwright> \
       node аудит/проби/рв6_стенд.js http://127.0.0.1:8765 /tmp/стенд /tmp/pyodide <сід>
   Аргументи: <база> <корінь зі зібраним index.html> <тека pyodide v0.26.4> <сід, типово 3>.
   `http.server` НЕ потрібен: усе з кореня віддає `route()` з диска; база — лише
   адреса, за якою сторінка бачить сама себе й міст. */
const { chromium } = require('playwright');
const fs = require('fs'), path = require('path');
/* РЯДОК 2671: файл сцен з Windows-checkout несе `\r` у кінці рядка, і останнє поле сцени
   (`OTSINKA=0\r`) не дорівнювало '0' — «Оціни мій образ» бігло в кожному прогоні (40–67 с).
   Хвіст `\r`/`\n` знімається з кожної змінної оточення до першого читання. */
for (const к of Object.keys(process.env)){
  const v = process.env[к];
  if (/[\r\n]+$/.test(v)) process.env[к] = v.replace(/[\r\n]+$/, '');
}
/* SLABKA=<форма,…> — слабка модель поверх заглушки (рядок 208, `слабка_модель.js`) */
const СЛАБКА = require(path.join(__dirname, 'слабка_модель.js'));
/* CHASY=1 / ZATRYMKA=… — годинник збору (наряд Ш-1, `часи_збору.js`); без них — як доти */
const ЧАСИ = require(path.join(__dirname, 'часи_збору.js'));
const БАЗА = process.argv[2] || 'http://127.0.0.1:8765', КОРІНЬ = process.argv[3] || process.cwd();
const ТЕКА_PYODIDE = process.argv[4] || '/tmp/pyodide';
/* СІД — пʼятим аргументом (або env `SEED`, латиницею: кириличних імен env
   оболонка не має). РВ-6 §3 вимагає 12 сідів; один прогін = один сід. */
const СІД = Number(process.argv[5] || process.env.SEED || 3);
const с = мс => new Promise(р => setTimeout(р, мс));
const НОМЕР = /#\d+\s*[·.\-]\s*\d{2}/, HEX = /#[0-9a-fA-F]{6}\b/, КОД = /\b[KR]-[A-Z]{2,6}-\d{2}\b/;
/* id вигаданих речей рук 3–4 (`розбір_відповідей.py`: offer id="м-%03d") — той
   самий шаблон, що чистка показу знімає в `безМашинногоСліду` (#173, «спостере-
   ження, не правлене»: «м-001» доходило до картки повз усі патерни вище). */
const ІД_ВИГАД = /(?<![A-Za-zА-Яа-яІіЇїЄєҐґ0-9])м-\d{3,}(?![A-Za-zА-Яа-яІіЇїЄєҐґ0-9])/;
/* `repr` словника чи списку Python і серіалізоване повідомлення внутрішньої мови в тексті
   для жінки (Ч-3). Вузько: у людському реченні «{'», «[{» і «"statements"» не трапляються. */
const РЕПР_ОБЄКТА = /\{['"]|\[\{|"statements"|'kind'/;
/* Стелі малювання картки нема (рядок 1447, п.9: «без обрізання»): доти `НА_КАРТЦІ_ПИТАНЬ = 12`;
   тепер картка малює всі речення шару, а питання `для_всіх` (однакові для кожної жінки) — лише у
   звіті. Звірка «розгорнутий перелік» нижче рахує рівність. */
let провалів = 0;
/* ── ІНСТРУМЕНТ РУЧНОГО ОГЛЯДУ (CLAUDE.md п.10; рядок 138 дошки) ─────────────
   Куратор робив цей прохід у себе руками: телефонна ширина, знімок кожного
   екрана й кожної з ЧОТИРЬОХ карток (не лише видимої), плюс видимий текст
   карток файлом — саме на такому знімку й побачено «схему обере ші» та
   неправду про крамницю на руках 3–4. Тепер прохід живе в репозиторії.
   ТРИ ЗМІННІ ОТОЧЕННЯ, І БЕЗ НИХ СТЕНД ПОВОДИТЬСЯ ТОЧНО ЯК ДОТИ:
     ZNIMKY=<тека> — знімки 390×844, `картки.txt` / `текст_екранів.txt` і
                     `розміри_запитів_seedN.txt` (наряд Л-2: розмір кожного запиту);
     FOTO_RECHI=a.jpg,b.jpg — кілька її фото в ОДНУ репліку (наряд Л-2);
     STELIA=<симв>  — інша стеля входу мосту, щоб міряти те, що на справжній впало б;
     FOTO=1        — пускати фото крамниць (доти вся зовнішня мережа глушилась);
     NE_TSIA=1     — сцена 4в (рядок 149): «не ця» → «Зібрати ще раз», речі руки 1 ДО/ПІСЛЯ;
     KOMENT=1      — сцена 4и (наряд С-2): коментар «своїми словами» → «Зібрати ще раз»;
                     KOMENT_TEKST=<текст> міняє сам коментар;
     HOLOS=1       — сцени 1д/4д/4е (рядок 167): підставне розпізнавання голосу в обох полях;
     ZNOVU=1       — сцена 4є (рядок 159): «Зібрати ще раз» двічі, картки рук 1–2 кожного збору;
     OTSINKA=0     — пропустити сцену 6 (Л-6, «Оціни мій образ»: два фото → оцінка → картка);
     OTSINKA=poroznia — сцена 6, коли модель відповіла `{"items": []}` (рядок 239): чесне повідомлення замість картки;
     FORMY=0       — заглушка-перекладачка відповідає ЦІЛИМ (Р-10): здоровий шлях карток
                     рук 3–4 і скільки викликів шару картка коштує без провокації 26.09;
     ZAPYS=korotkyi — К-3: річ у пулі коротким записом (коди розбору й рядок особливостей);
     CHASTYN=2|3   — К-3 варіант «б»: пул руки 1 частинами, запити одночасно (час — рядком руки 1);
     PODIIA=bez_kodu — Ч-5: перекладачка кладе названу подію лише в event, без коду й смуги;
     ZHYVA=sonnet|haiku — на шві мосту відповідає ЖИВА модель Claude через `claude -p`
                     по підписці (наряд Ж-1, CLAUDE.md п.15); без неї — заглушка, як доти;
     DO=rozmova    — НГ-4: лише перший хід розмови (CHAT_TEXT), паспорт із вимірами й знімки екрана
                     сценарію — без палітри й збирання образів;
     ZAMINA=1      — ФОТО-1: заглушка опису рук 1–2 пропонує заміну першої речі з кадром (colour), а
                     другий опис (з `swap_spares`) обирає першу запасну — шлях заміни в браузері цілим;
     ZVIT_OUT      — вже було: звіт вердиктів файлом.
   Імена латиницею: оболонка кириличних env не має (той самий урок, що в
   `стенд_pyodide_кеш.sh`). */
const ЗНІМКИ = process.env.ZNIMKY || null;
const ЗАМІНА_СТЕНДА = process.env.ZAMINA === '1';
/* ФОТО-1: що заглушка кладе в `swap` опису під ZAMINA=1 — друга половина (є `swap_spares`) обирає
   першу запасну; перша — пропонує першу річ образу з кадром (не її річ). Без ручки — нічого. */
function заміноюЗаглушки(об){
  if (!ЗАМІНА_СТЕНДА || !об || !об.task) return null;
  if (об.swap_spares) return {item: об.swap_spares.item, why: об.swap_spares.why || 'colour',
                              to: ((об.swap_spares.spares || [])[0] || {}).n};
  const р = (((об.outfit || {}).items) || []).find(x => (x.photos || []).length && !x.hers);
  return р ? {item: р.n, why: 'colour'} : null;
}
/* КАРТ-1: що картка сценарію каже в «Де» й «Ошатність» і яке число дала модель (ПАСПОРТ_П.ошатність) — для проби `карт1_картка.py` */
const КАРТКА_РЯДКИ = () => ({де: (document.getElementById('зн-місце') || {}).textContent, ошатність_картки: (document.getElementById('зн-дрес') || {}).textContent,
  діапазон_рядок: (document.getElementById('сц-діапазон') || {}).textContent, нагода: (document.getElementById('зн-нагода') || {}).textContent,
  коли: (document.getElementById('зн-коли') || {}).textContent, число_моделі: (() => { const п = (typeof паспортКартки === 'function') ? паспортКартки() : ((typeof ПАСПОРТ_П !== 'undefined') ? ПАСПОРТ_П : null); return (п && п.ошатність) || null; })(),
  дрес_код_моделі: (typeof ПАСПОРТ_П !== 'undefined' && ПАСПОРТ_П) ? (ПАСПОРТ_П.дрес_код || null) : null,
  година_моделі: (typeof ПАСПОРТ_П !== 'undefined' && ПАСПОРТ_П) ? (ПАСПОРТ_П.година == null ? null : ПАСПОРТ_П.година) : null});
const ФОТО_КРАМНИЦЬ = process.env.FOTO === '1';
/* Стеля очікування одного кадру крамниці під `FOTO=1` — та сама, що `КАДР_ЧЕКАТИ_МС`
   у показі (Ф-143): прилад не має терпіти довше, ніж терпить сам продукт. */
const КАДР_ТАЙМАУТ_МС = Number(process.env.FOTO_TIMEOUT || 12000);
/* НАМІР ПАСПОРТА — РУЧКОЮ (рядок 155, 24.09.2026). Сценарна модель писала
   `намір: 'conventional'` константою, тож стенд НІКОЛИ не ходив шляхом сміливих
   намірів (statement / fashion_forward / editorial) — а саме там `composer`
   тримає живими 17 слотів замість менших, добуток ядра переростає 2³¹−1 і
   збирання в Pyodide падало OverflowError. Без `NAMIR` прогін байт-у-байт той
   самий, що доти. Ім'я латиницею — оболонка кириличних env не має. */
const НАМІР_СТЕНДА = process.env.NAMIR || 'conventional';
/* ПАСПОРТ БЕРЕ РІВНО ЧОТИРИ НАМІРИ, І ПІДПИС НЕ МАЄ ПРАВА ЦЬОГО ХОВАТИ
   (куратор, 24.09.2026). `паспорт_нагоди.py:905` пропускає лише ці чотири
   (K-PER-00, `реєстр_правил.INTENT`); `fashion_forward` і `editorial` він
   МОВЧКИ читає як `conventional`. Перша версія цієї ручки підписувала звірку
   значенням ручки, тож прогін із `NAMIR=fashion_forward` ставив ✔ «намір
   fashion_forward», а сторінка збирала conventional — прилад брехав про те,
   що саме перевірив. Тепер підпис береться з ПАСПОРТА, як його прийняла
   сторінка (`намірСторінки`), а невідповідність ручки називається окремим
   рядком. Самі наміри паспорта тут НЕ розширюються: це поза нарядом. */
const НАМІРИ_ПАСПОРТА = ['conventional', 'statement', 'comfort_first', 'context_optimal'];
const намірСторінки = async стор => стор.evaluate(
  () => (typeof ПАСПОРТ_П !== 'undefined' && ПАСПОРТ_П && ПАСПОРТ_П.намір) || '(паспорта нема)');
/* ЗБІЙ ЗБИРАННЯ — ОДНА ОЗНАКА НА ВЕСЬ СТЕНД, І ВОНА НЕ ЗІ СЛІВ ЖІНЦІ. Доти
   очікування виглядали на текст `Не вимальовувалось` у `#зб-статус` — тобто на
   формулювання для людини, яке рядок 155 і переписує. Тепер ознака технічна:
   `ЗБ.діагноз` несе рядок `build · failed:` (його там ставить `показ.html`; Ч-8 — кодами), а
   текст статусу лишається другим свідком для сумісності. */
const ВИРАЗ_ЗБОЮ = "((typeof ЗБ !== 'undefined' && ЗБ && (ЗБ.діагноз || [])"
  + ".some(р => /^build · failed/.test(р)))"
  + " || /build · failed|Образи не зібрались|Не вимальовувалось|TypeError/"
  + ".test((document.getElementById('зб-статус') || {}).textContent || ''))";
/* NE_TSIA=1 — сцена 4в (рядок 149): «не ця» на картці руки 1 → «Зібрати ще
   раз» → речі руки 1 ДО/ПІСЛЯ. Коштує ще одного повного збору, тож за
   змінною: без неї прогін той самий, що й доти. */
const НЕ_ЦЯ_СТЕНД = process.env.NE_TSIA === '1';
/* KOMENT=1 — сцена 4и (наряд С-2): коментар «своїми словами» → «Зібрати ще раз». Коштує
   ще одного повного збору, тож за змінною: без неї прогін той самий, що й доти.
   KOMENT_TEKST=<текст> — інший коментар; типовий — той, що просить наряд. */
const КОМЕНТАР_СТЕНД = process.env.KOMENT === '1';
/* ТИПОВИЙ КОМЕНТАР НЕСЕ ДВІ МЕЖІ, І ЦЕ НАВМИСНО. «Без каблука» типовий сценарій стенда
   (`ЧАТ_ТЕКСТ`: «…без підборів») вже має межею — тобто звірка «межа з коментаря стала
   межею паспорта» на ній була б ЗЕЛЕНОЮ Й БЕЗ ЦІЄЇ ПРАВКИ, тобто нічого не міряла б.
   Тому поруч стоїть межа, якої в сценарії нема («без принта»): саме на ній видно, що
   коментар СПРАВДІ долив межу, а не повторив уже чинну. Сам «каблук» лишається — його
   просить наряд, і на ньому видно, що повтор чинної межі нічого не ламає. */
const КОМЕНТАР_ТЕКСТ = process.env.KOMENT_TEKST || 'взуття не моє, хочу без каблука і без принта';
/* ZNOVU=1 — сцена 4є (рядок 159): «Зібрати ще раз» двічі поспіль; після кожного
   збору — знімки й речі карток рук 1–2 і лічба речей, що повторились із
   попередніх зборів. Два повні збори — тому за змінною, як і 4в. */
const ЗНОВУ_СТЕНД = process.env.ZNOVU === '1';
/* ZBIR2=<репліка> (наряд Н-1, 27.09.2026) — ДРУГИЙ ЗБІР ІНШИМ СЦЕНАРІЄМ У ТОМУ
   САМОМУ СЕАНСІ, А ВЕРДИКТ — КАРТЦІ ПЕРШОГО. Власник 25.09 віддав файл вердиктів,
   у якому `паспорт`, `чат` і діагноз руки були станом ОСТАННЬОГО збирання на мить
   вердикта, а не того прогону, якому вердикт поставлено (журнал куратора 26.09).
   Відтворити це стенд не міг: він знав рівно ОДИН збір за прогін, тож «чужий
   паспорт у вердикті» на ньому не мав де з'явитись. Сцена 4з нижче робить другий
   збір, тоді йде в «Усі образи» (`#до-бібліотеки` → `#е-бібліотека`), тапає плитку
   ПЕРШОГО збору, як палець жінки, і ставить їй вердикт.
   Без змінної прогін БАЙТ-У-БАЙТ той самий: сцени просто нема. Ім'я латиницею —
   оболонка кириличних env не має (той самий урок, що в ZNIMKY). */
const ДРУГИЙ_ЗБІР = process.env.ZBIR2 || null;
/* Підписи плиток бібліотеки — `показ.html:ЧИСЛА_Б`. Тут вони лише для ПОШУКУ
   плитки очима приладу; продукт цього масиву від стенда не бере. */
const ЧИСЛА_Б_СТЕНДА = ['Перший', 'Другий', 'Третій', 'Четвертий', "П'ятий", 'Шостий'];
/* PYTANNIA=1 (рядок 151) — пройти шлях «Відповісти на три питання» БЕЗ ПОРТРЕТА:
   палітра → кнопка ноти → аркуш «Що тобі до лиця» → три відповіді → назад на
   палітру. Портрета в стенда нема за побудовою (кольори він бере тим самим
   шляхом «через будь-який чат-помічник», що й жінка без знімка), тож це рівно
   той випадок, у якому куратор знайшов глухий кут. Без змінної прохід той
   самий, що доти, — байт у байт. */
const ТРИ_ПИТАННЯ = process.env.PYTANNIA === '1';
/* PRYMIRKA=1 (рядок 160) — натиснути «Приміряти на себе» на ДВОХ картках поспіль
   і звірити, що картинки різні й кожна своєї картки. Тестувальниця «Ір» записала
   вердикт «повтор зображення з попереднього опису»: картинка однієї картки
   повторювала картинку сусідньої. Заглушка картинки тут віддає на кожен виклик
   СВІЙ кадр із власним кольором, тож повтор на екрані означав би повтор у коді
   сторінки, а не збіг двох відповідей моделі. `IMG_DROP=0,2` — скільки фото
   речей «не дійшло» на кожному виклику (заголовок `x-images-dropped`
   справжнього воркера); `IMG_DELAY` — як довго малюється кожен кадр.
   Без змінної прогін той самий, байт у байт. */
const ПРИМІРКА = process.env.PRYMIRKA === '1';
/* HOLOS=1 (рядок 167) — ПІДСТАВНЕ РОЗПІЗНАВАННЯ ГОЛОСУ. Справжнього в headless
   Chromium нема (служба розпізнавання ходить у мережу, яку прилад глушить), тож
   голос міряється тим самим способом, що й модель: заглушкою на шві. Ручка
   впорскує в сторінку `window.SpeechRecognition`, який на `start()` віддає
   український текст, а на `stop()` — `onend`. Диктування в розмову промовляє
   САМЕ `ЧАТ_ТЕКСТ`: інакше всі звірки випадку нижче міряли б інший сценарій, і
   прогін із голосом не було б із чим порівняти. У «Своїми словами» промовляється
   речення власника з наряду.
   БЕЗ ЦІЄЇ ЗМІННОЇ ПРОГІН БАЙТ-У-БАЙТ ТОЙ САМИЙ: заглушка не впорскується,
   сцена 1 як доти тисне `fill`, сцен 1д, 4д і 4е нема. ЛІТЕРИ 1д і 4д/4е, А НЕ
   1г/4г: «1г» у цьому файлі вже зайняла репліка поза сценарієм (рядок 157,
   `DOVIDKA_TEXT`), «4г» — приміряння (рядок 160, `PRYMIRKA=1`), і дві різні сцени
   під однією літерою робили б друк прогону нечитним. */
const ГОЛОС_СТЕНД = process.env.HOLOS === '1';
const ГОЛОС_ВЕРДИКТУ = "в суботу весілля подруги о п'ятій, хочу щось легке";
/* SHYRYNA=<px> — ширина телефонного вікна (типово 390). Латиницею, з тієї ж причини, що
   ZNIMKY: кириличних env оболонка не має. Потрібне рядкові 174: на 360 px перелік меж іде
   вже в ТРИ рядки, і саме там видно, чи картка росте під вміст, чи її ріже контейнер. */
const ТЕЛЕФОН = {width: Number(process.env.SHYRYNA) || 390, height: 844};
/* SHARY (рядок 158): пара шарів тестувальниці в образах заглушки — див. `відповісти`. */
const ПАРА_ШАРІВ = process.env.SHARY || null;
let ПАРУ_НАДРУКОВАНО = false;
/* ── ЧУЖИЙ СЦЕНАРІЙ БЕЗ ЛАТАНОЇ КОПІЇ (рядок 146 дошки) ──────────────────────
   Куратор проходив «побачення в ресторані о 20:00, дощ, +5» копією стенда, у
   якій руками підмінив репліку чату й паспорт заглушки. Тепер це дві змінні:
     CHAT_TEXT — репліка жінки в чаті сценарію (типово — офісна, як доти);
     PASPORT   — JSON, що НАКЛАДАЄТЬСЯ поверх паспорта заглушки (`паспортМоделі`):
                 ключі з нього перекривають типові, решта лишається офісною —
                 КРІМ трьох слів жінки саме про офіс (рядок 154): дрес-коду,
                 настрою й межі ніг. Модель, яка почула про похорон, «business
                 casual» не вигадала б; хочеш їх — назви в PASPORT. Порада
                 заглушки під PASPORT — теж без «для офісу».
   БЕЗ НИХ ПРОГІН БАЙТ-У-БАЙТ ТОЙ САМИЙ: `Object.assign` із порожньою накладкою
   віддає той самий обʼєкт у тому самому порядку ключів. З ними звірки офісного
   випадку (нагода й місце, чипи вето, рядок випадку, питання до людини)
   звіряються з ПОДАНИМ паспортом і мають інші назви (рядок 154); решта звірок
   міряє типовий шлях, як і доти. */
/* порожній CHAT_TEXT — законний сценарій (рядок 152: фото речі без слів), тому `in`, а не `||` */
const ЧАТ_ТЕКСТ = ('CHAT_TEXT' in process.env) ? process.env.CHAT_TEXT
  : 'робочий день в офісі, дрес-код business casual, без підборів';
const ПАСПОРТ_НАКЛАДКА = process.env.PASPORT ? JSON.parse(process.env.PASPORT) : null;
if ('CHAT_TEXT' in process.env || ПАСПОРТ_НАКЛАДКА)
  console.log('СЦЕНАРІЙ ПІДМІНЕНО (CHAT_TEXT/PASPORT): звірки офісного випадку звіряються з поданим паспортом ·',
              JSON.stringify({чат: ЧАТ_ТЕКСТ, паспорт: ПАСПОРТ_НАКЛАДКА}));
/* ── РЯДОК 152: FOTO_RECHI=<jpg> — фото речі в ту саму репліку (кнопка біля «надіслати»);
   заглушка тоді відповідає й полем `речі_з_фото` (з PASPORT або типовою сукнею). Без неї — як доти. */
const ПАСПОРТ_ПОВЕРХ = ПАСПОРТ_НАКЛАДКА;
/* ДВА ЇЇ ФОТО В ОДНІЙ РЕПЛІЦІ — КОМОЮ (наряд Л-2, 26.09.2026). Доти `FOTO_RECHI`
   брав ОДИН файл, і найдорожчий випадок 413 (два її фото base64 у тому самому
   `messages`, прогін власника 25.09) стенд відтворити не міг зовсім. Тепер
   `FOTO_RECHI=спідниця.jpg,чоботи.jpg` — і заглушка паспорта називає по речі на
   кожне фото, у тому самому порядку. Один файл — як доти, байт-у-байт. */
const ФОТО_РЕЧІ_СПИСОК = String(process.env.FOTO_RECHI || '').split(',').map(x => x.trim()).filter(Boolean);
const ФОТО_РЕЧІ = ФОТО_РЕЧІ_СПИСОК[0] || null;
/* П-4: PORTRET=<jpg> — портрет на першому кроці знайомства: кольори читає сама сторінка (промпт
   збирача `міст_вхід.ЧИТАННЯ_ПОРТРЕТА`); PORTRET_VIDMOVA=1 — перший виклик відмовляє кодом,
   рядок причини пише перекладачка. DOVIDKA_PYTANNIA=<питання> — питання про застосунок на палітрі. */
const ПОРТРЕТ = process.env.PORTRET || null;
const ПОРТРЕТ_ВІДМОВА = !!process.env.PORTRET_VIDMOVA;
/* ZHINKA=<json> — кольори тестової жінки з файлу {skin:[3], hair:[2], eyes, ring} замість типової «Проби РВ-6»
   (низький контраст). Потрібна замірові різних жінок (ЗАМІР-Ш): контраст обличчя, підтон. Без змінної — як доти. */
const ЖІНКА = process.env.ZHINKA ? JSON.parse(fs.readFileSync(process.env.ZHINKA, 'utf8'))
  : {skin: ['#deb295', '#d8a98c', '#e2ba9f'], hair: ['#f1dbaa', '#d9bf88'], eyes: '#759087', ring: '#3f4f49'};
/* П-7: VYBIR_PALITRY=proza — заглушка відповідає на вибір палітри прозою (не JSON), щоб пройти
   чесний шлях «стилістка не обрала» (ранг коду, P8 «без входу»); без змінної — вибір кодами */
const ВИБІР_ПАЛІТРИ_ПРОЗОЮ = process.env.VYBIR_PALITRY === 'proza';
let портретВідмовлено = 0;
const ДОВІДКА_ПИТАННЯ = process.env.DOVIDKA_PYTANNIA || null;
const РІЧ_ТИПОВА = {фото: 'ф1', назва: 'сукня з фото', слот: 'сукня', колір: 'червоний', матеріал: null,
  крій: 'fitted', довжина: 'міді', принт: 'однотонний', ошатність: 6, чия: 'невідомо',
  рамка: {ліво: 150, верх: 80, право: 850, низ: 960}};
/* друга й далі речі — інші слоти, інакше `закріпити` лишило б одну: спідниця
   займає «низ», чоботи — «взуття» (`річ_з_фото._ЗАЙМАЄ`) */
const РЕЧІ_ДОДАТКОВІ = [
  {фото: 'ф2', назва: 'чоботи з фото', слот: 'взуття', колір: 'чорний', матеріал: null,
   крій: null, довжина: null, принт: 'однотонний', ошатність: 5, чия: 'моя',
   рамка: {ліво: 120, верх: 200, право: 880, низ: 900}},
  {фото: 'ф3', назва: 'сумка з фото', слот: 'сумка', колір: 'бежевий', матеріал: null,
   крій: null, довжина: null, принт: 'однотонний', ошатність: 5, чия: 'моя',
   рамка: {ліво: 150, верх: 150, право: 850, низ: 850}}];
/* перше фото — типова річ (як доти), решта — по речі на фото, у порядку вкладень */
const РЕЧІ_З_ФОТО_СТЕНДА = () => [РІЧ_ТИПОВА].concat(РЕЧІ_ДОДАТКОВІ.slice(0, Math.max(0, ФОТО_РЕЧІ_СПИСОК.length - 1)));
/* ── РЯДОК 157: DOVIDKA_TEXT=<репліка> — вона пише поза сценарієм (екран палітри, тема
   «довідка») про СВОЮ річ чи вимогу до образу. Заглушка помічниці відповідає рівно так, як
   відповіла жива модель тестувальниці «Ір» («обов'язково врахуємо…»), — щоб було видно, що
   цю обіцянку жінка не бачить. Заглушка паспорта бере річ З КЛАУЗИ, яку код поклав в абзац
   «РІЧ СЛОВАМИ» як певну, — або не повертає нічого, коли код її не впізнав (повернення
   куратора 24.09: доти заглушка повертала джинси на БУДЬ-ЯКИЙ текст, і заперечення на стенді
   не було видно). «Непевну» клаузу заглушка, як обережна модель, не додає.
   DOVIDKA_MOVCHYT=1 — модель не повертає нічого (певну річ ставить код сам);
   DOVIDKA_ZAPER=1 — репліка заперечна чи не про її річ: очікується, що вона лишиться в
   помічниці, у паспорті речі нема, на картках — теж. */
/* PODIIA=bez_kodu (Ч-5, 27.09.2026) — перекладачка кладе названу подію ЛИШЕ в event: без коду
   місця за підписом плитки й без смуги. Так відповіли MamayLM і Lapa на «…для походу на концерт»
   у живому замірі на ноутбуці (3 з 3, температура 0). Без змінної заглушка, як доти, бере код
   місця з ноти плитки («Зал: театр, кіно, концерт…»). */
const ПОДІЯ_БЕЗ_КОДУ = /^bez_kodu$/.test(String(process.env.PODIIA || ''));
const ДОВІДКА_ТЕКСТ = process.env.DOVIDKA_TEXT || null;
/* М-5 (п.14): ROZMOVA=<json> — розмова кількома листами після першого (сцена 1ж): [{вона, після, need?,
   text?, чекаємо}]. Заглушка моделі розмови відповідає на ці листи оновленням `після` — тим, що зробила б
   сумлінна модель, яка бачить розмову й паспорт; без змінної прогін той самий, що доти. */
const РОЗМОВА_СТЕНДУ = process.env.ROZMOVA ? JSON.parse(fs.readFileSync(process.env.ROZMOVA, 'utf8')) : null;
const ДОВІДКА_МОВЧИТЬ = !!process.env.DOVIDKA_MOVCHYT;
const ДОВІДКА_ЗАПЕР = !!process.env.DOVIDKA_ZAPER;
/* у репліці — ЇЇ річ ствердно (присвійне слово, і тестувальник не позначив її заперечною);
   вимога без її речі («хочу екосумку») речі в паспорт не кладе — це бажання */
const ДОВІДКА_ЇЇ_РІЧ = !!ДОВІДКА_ТЕКСТ && !ДОВІДКА_ЗАПЕР
  && /(^|[^\p{L}])(в мене|у мене|мій|моя|моє|мої|свій|своя|свої|свою)([^\p{L}]|$)/iu.test(ДОВІДКА_ТЕКСТ);
const СЛОТ_157 = [[/джинс|штан|спідниц/i, 'низ'], [/сукн/i, 'сукня'], [/пальт|куртк|тренч/i, 'верхній_шар'],
  [/кросівк|туфл|черевик|чобот/i, 'взуття'], [/светр|блуз|сорочк/i, 'верх'], [/сумк/i, 'сумка']];
const річЗКлаузи = клауза => {
  const сл = (СЛОТ_157.find(([р]) => р.test(клауза)) || [])[1];
  if (!сл) return null;
  const назва = клауза.replace(/^(в мене|у мене|мій|моя|моє|мої|свій|своя|свої|свою)\s+(є\s+)?/iu, '').trim();
  return {фото: null, назва, слот: сл, колір: /світл\S* джинс/i.test(клауза) ? 'блакитний' : null, матеріал: null,
    крій: null, довжина: null, принт: null, ошатність: null, чия: 'моя'};
};
const ОБІЦЯНКА_157 = /врахуємо|врахую|запам.ятаю|візьму до уваги/i;
/* СЛОВНИК ЗАГЛУШКИ РУК 3–4 (П-1): жива модель слот знає сама й називає кодом, а заглушка
   мусить його якось дати — вгадує словом назви РІВНО тих речей, які пише сама, і її речей
   зі сценаріїв стенда. Продукт цього словника не читає. */
const СЛОТИ_СТУБ = [[/сукн|dress/i, 'сукня', 'dress'], [/спідниц|джинс|штан|шорт|skirt|jeans|trousers/i, 'низ', 'bottom'],
  [/козак|чобот|туфл|кросів|кед|черевик|ботфорт|лофер|boots|shoes|loafer/i, 'взуття', 'shoes'],
  [/тренч|пальт|куртк|плащ/i, 'верхній_шар', 'outerwear'],
  /* Ч-6: слова верхів, які словник пропускав («Майка … SINGLE» ішла в запасний 'верх'
     і слотом НЕ вважалась) — через це порада про заправлений верх не з'являлась там,
     де окремі верх і низ у образі справді є. */
  [/светр|блуз|сороч|топ|джемпер|кардиган|майк|футболк|водолазк|лонгслів|sweater|blouse/i, 'верх', 'top'],
  [/сумк|клатч|шопер|bag/i, 'сумка', 'bag'], [/хустк|шарф|scarf/i, 'шарф', 'scarf']];
const СЛОТ_СЛОВОМ_СТУБ = н => ((СЛОТИ_СТУБ.find(([р]) => р.test(н)) || [])[1]) || 'верх';
const КОД_СЛОТА_СТУБ = н => ((СЛОТИ_СТУБ.find(([р]) => р.test(н)) || [])[2]) || 'top';
/* ТЕ САМЕ, АЛЕ БЕЗ ЗАПАСНОГО «верх» (наряд Ч-6): опис має знати, чого в образі НЕМА, а
   `СЛОТ_СЛОВОМ_СТУБ` кожну невпізнану назву («Ремінь жіночий Welfare») кличе верхом — і
   порада «верх заправити» ставала правдоподібною там, де верху нема зовсім. */
const СЛОТ_ЯКЩО_ВПІЗНАВ = н => ((СЛОТИ_СТУБ.find(([р]) => р.test(н)) || [])[1]) || null;
/* що займає річ в образі — та сама таблиця, що `річ_з_фото._ЗАЙМАЄ` */
const ЗАЙМАЄ_152 = {сукня: ['сукня', 'комплект', 'верх', 'низ'], комплект: ['сукня', 'комплект', 'верх', 'низ'],
  верх: ['верх', 'сукня', 'комплект'], низ: ['низ', 'сукня', 'комплект']};
/* «ші» ОКРЕМИМ СЛОВОМ у ВИДИМОМУ тексті (рядок 138, рішення власника п.7).
   Не grep по коду: імена класів (`.ші`, `#ші-панель`) і поля (`хто:'ші'`)
   лишаються, бо їх людина не бачить. Міряється рівно `innerText` екрана. */
const ВИДИМЕ_ШІ = /(?<![\p{L}'\u2019-])[шШ][іІ](?![\p{L}'\u2019-])/gu;
const лічитиШІ = т => (String(т || '').match(ВИДИМЕ_ШІ) || []).length;
/* `що ?? null`, а не `що`: `JSON.stringify(undefined)` віддає undefined, і
   `.slice` на ньому валить УВЕСЬ прохід (тестувальниця, 24.09: живий прогін
   сіда 7 помер на звірці «знахідки суду лишились структурою» — перша картка
   була руки 3, а в неї `знахідки_коду` нема за побудовою). Прилад не має права
   вмирати на тому, що звірка червона: червона звірка — це її робота. */
const ф = (н, у, що) => { if (у) console.log('  ✔ ' + н); else { провалів++; console.log('  ✗ ' + н + '  →  ' + String(JSON.stringify(що ?? null)).slice(0, 400)); } };

/* ── лічильники фраз усередині ПОВНОГО тексту пакета (для рв6_підсумок.py, рядок
   «стенд після хвилі 19.09»): не звірка, лише друк — рахує, скільки РАЗІВ повний
   текст, який бачить модель, несе рядок конкретного правила. На відміну від
   ЗБ.діагноз (лише перші 5 «код не знає» на картку), тут видно ввесь пакет. */
const ЛІЧБА_ФРАЗ = {};
