/* НГ-5 (рядок 754): частина дня, яку подія зазвичай має без слова «вечір» у назві — заглушка грає правило
   промпту ходу плиток (театр, концерт, опера — вечір) своєю таблицею, як ошатність — `СТЕНД_ОШАТНІСТЬ_МІСЦЯ`. */
