  await стор.click('#зб-зібрати', { noWaitAfter: true });
  /* Знімки САМОГО екрана збирання (наряд Ч-11): один раз на 8 с, доки йдуть руки.
     Саме тут, а не нижче: нижче стенд уже дочекався чотирьох карток, і екран
     збирання позаду. `знімокЙде` — щоб довгий знімок не наклався на наступний. */
  let знімківЗбирання = 0, знімокЙде = false;
