  let рука1За = '?';
  /* ЧЕКАННЯ КІНЧАЄТЬСЯ Й НА ЗБОЇ (рядок 155, 24.09.2026). Доти це очікування
     дивилось ЛИШЕ на появу картки руки 1 і не дивилось на `#зб-статус`: коли
     збирання падало на першій же секунді, прилад стояв тут усі 900 с, потім ще
     900 на наступному очікуванні й 1 500 на останньому — сорок хвилин, щоб
     сказати те, що видно відразу. Саме тому стенд не спіймав OverflowError під
     сміливим наміром: у CI прогін просто не дочікувався. Тепер обидва
     очікування кінчаються на `ВИРАЗ_ЗБОЮ`, а звірка нижче називає ✗. */
  try {
    await стор.waitForFunction("(typeof ЗБ !== 'undefined' && ЗБ && Array.isArray(ЗБ.картки)"
        + " && ЗБ.картки.some(к => к && к.рука === '1')) || " + ВИРАЗ_ЗБОЮ, null, { timeout: 900000 });
    рука1За = (await стор.evaluate(ВИРАЗ_ЗБОЮ))
      ? 'збирання впало — далі не чекаємо'
      : ((Date.now() - тЗапити) / 1000).toFixed(1) + ' с';
  } catch (_) { рука1За = 'не дочекався (900 с)'; }
  /* ПІДПИС — З ПАСПОРТА, НЕ З РУЧКИ. Ручка лише ПРОСИТЬ намір; що з нього
     вийшло, знає сторінка, і саме це має стояти в логу й у звірці. */
  const намірУПаспорті = await намірСторінки(стор);
  if (!НАМІРИ_ПАСПОРТА.includes(НАМІР_СТЕНДА))
    console.log('   ⚠ NAMIR=' + НАМІР_СТЕНДА + ' — поза чотирма намірами паспорта ('
      + НАМІРИ_ПАСПОРТА.join('/') + '), `паспорт_нагоди` читає його як conventional;'
      + ' підпис нижче — те, що СПРАВДІ прийняла сторінка');
  if (намірУПаспорті !== НАМІР_СТЕНДА)
    console.log('   ⚠ просили намір «' + НАМІР_СТЕНДА + '», паспорт узяв «' + намірУПаспорті + '»');
  console.log('   рука 1: картка за ' + рука1За + ' (від запити) · намір паспорта ' + намірУПаспорті);
  await стор.waitForFunction("document.querySelectorAll('#картки .картка').length >= 4 || "
      + ВИРАЗ_ЗБОЮ, null, { timeout: 900000 });
  const збій = await стор.evaluate(() => ({статус: (document.getElementById('зб-статус') || {}).textContent || '', поломка: ЗБ.поломка && ЗБ.поломка.назва, карток: document.querySelectorAll('#картки .картка').length}));
  console.log('\n2. збирання (сід ' + СІД + ') за', ч(), '· поломка руки 2:', JSON.stringify(збій.поломка), '· статус:', JSON.stringify(збій.статус.slice(0, 160)));
  /* ЛАТКИ В СТОРІНЦІ ТУТ БІЛЬШЕ НЕМА. 16.09 стенд підміняв `містП`, щоб обійти
     `псування_сценарію.join is not a function` (РВ-6 З-1) і домірити решту; ту
     поломку продукту вже полагоджено (`показ.html` тепер приймає і рядок, і
     масив), а прилад, який сам латає сторінку, більше не каже правди про неї.
     Падає збирання — падає звірка, і далі стенд іде з тим, що є. */
  const впало = await стор.evaluate(ВИРАЗ_ЗБОЮ);
  ф('збирання на опублікованій сторінці не падає (намір паспорта ' + намірУПаспорті + ')',
    збій.карток >= 4 && !впало,
    (збій.статус.slice(0, 200) || '') + ' · діагноз: '
      + JSON.stringify(await стор.evaluate(() => ((typeof ЗБ !== 'undefined' && ЗБ && ЗБ.діагноз) || [])
          .filter(р => /^build · failed/.test(р)).map(р => р.slice(0, 300)))));
  const поступ = setInterval(async () => { try {
    const с = await стор.evaluate(() => ({стадії: ЗБ.стадії, етап: ЗБ.етап, діагноз: (ЗБ.діагноз || []).slice(-2), статус: (document.getElementById('зб-статус') || {}).textContent}));
    console.log('   … ' + ч() + ' стадії ' + JSON.stringify(с.стадії) + ' етап ' + JSON.stringify(с.етап) + ' статус ' + JSON.stringify(String(с.статус || '').slice(0, 160)) + ' діагноз ' + JSON.stringify(с.діагноз).slice(0, 300));
  } catch (e) { console.log('   … ' + ч() + ' (стан недоступний: ' + String(e).slice(0, 80) + ')'); } }, 30000);
  await стор.waitForFunction("document.querySelectorAll('#картки .картка').length >= 4 || "
      + ВИРАЗ_ЗБОЮ, null, { timeout: 1500000 });
  clearInterval(поступ);
  if (знімкиЗб) clearInterval(знімкиЗб);
  if (ЗНІМКИ) {
    const рядки = await стор.evaluate(() => window.__поступ_рядки || []);
    const ш = path.join(ЗНІМКИ, 'postup_seed' + СІД + '.txt');
    fs.mkdirSync(ЗНІМКИ, {recursive: true});
    fs.writeFileSync(ш, рядки.join('\n----\n') + '\n');
    console.log('   екран збирання: ' + рядки.length + ' станів у ' + ш);
  }
  await с(1500);
  await СЛАБКА.підсумок(стор);
  /* `П` МОЖЕ БУТИ null, І ЦЕ ЗАКОННИЙ КІНЕЦЬ ШЛЯХУ (тестувальниця, 24.09):
     коли збирання впало до першого образу (на локальній моделі — «сценарію
     нема», бо модель назвала нагоду поза довідником), пакета нема зовсім, і
     `П.картки` кидало `Cannot read properties of null`. Прохід умирав одразу
     після того, як показ УЖЕ сказав жінці свій рядок, — тобто саме тоді, коли
     є що знімати й читати. Тепер картки просто порожні, а звірки нижче
     червоніють самі, як їм і належить. */
  const с2 = await стор.evaluate(() => ({
    картки: (((typeof П !== 'undefined' && П) || {}).картки || []).map(к => ({рука: к.рука, речей: (к.речі || []).length, фото: (к.речі || []).filter(р => р.фото).length,
      /* рядок 118: річ, у якої в каталозі НЕМА жодного власного знімка (фід дає лише
         службові картинки крамниці). Така йде на картку аркою, а не чужим фото. */
      без_свого: (к.речі || []).filter(р => !р.фото && !((р.фото_усі || []).length)).length,
      /* Л-4 (рядки 934, 1171, 1201): ходи картки СПИСКОМ (колонка журналу склеює їх «; », а причина моделі сама
         має «; »), і назви речей її складу — обидва ключі назви, показу й крамниці */
      свідомі_список: (Array.isArray(к.свідомі) ? к.свідомі : []).map(х => String((x_ => (x_ && x_.текст) || x_)(х) || '')),
      назви_обидві: (к.речі || []).flatMap(р => [String(р.назва || р.н || ''), String(р.назва_крамниці || '')]).filter(Boolean),
      /* рядок 1250: id речей складу картки й id речей кожного ходу (хід у хід зі `свідомі_список`) */
      ід_речей: (к.речі || []).map(р => String(р.id ?? '')).filter(Boolean),
      свідомі_ід: (Array.isArray(к.свідомі_ід) ? к.свідомі_ід : []).map(г => [].concat(г || []).map(String)),
      ціни: (к.речі || []).filter(р => р.ціна).length, текст: (к.текст || '').length, ітерацій: к.ітерацій, викликів: к.викликів,
      /* Т-8 (25.09.2026): назви речей і сама проза — щоб звірка нижче могла сказати,
         чи перелік на картці й текст під ним говорять про ОДИН образ. */
      назви: (к.речі || []).map(р => String(р.назва || р.н || '')), проза: String(к.текст || ''),
      /* П-3: з шаром проза лишається англійською (сирий вихід моделі), а назви на картці —
         перекладом шару; звірка «переліку й прози» бере назву, якою її дав перелік, — вхід шару */
      назви_до_шару: (к.речі || []).map((р, і) => ((к.мова_шару || []).map(з => (з.вхід || {})['річ.' + і + '.назва'])
        .find(Boolean)) || String(р.назва || р.н || '')),
      не_перекладено: (к.мова_не_перекладено || []),
      збій: !!к.збій, мова_видано: к.мова_видано, свідомі: (к.свідомі || []).length, різноманітність: !!к.різноманітність,
      /* Ч-2 (27.09.2026): `к.питання` — коди (правило + повідомлення); друкуємо їх тим самим
         переказом, що й колонка звіту, а поруч — речення, які з них склав шар */
      питань: (к.питання || []).length,
      /* рядок 1447: питань, які шар пише для картки, — без `для_всіх` (ті лише у звіті) */
      питань_картці: (к.питання || []).filter(п => п && п.повідомлення && п.повідомлення.kind && !п.для_всіх && !п.на_розгортання).length,
      /* рядок 2894: питання кольору `на_розгортання` — у підписі кнопки одразу, речення шар пише після дотику */
      чекають: (typeof чекаютьРозгортанняП === 'function') ? чекаютьРозгортанняП(к) : 0,
      для_всіх: (к.питання || []).filter(п => п && п.для_всіх).length,
      кнопка: к.питання_кнопка || null,
      питання: (к.питання || []).map(п => (typeof питанняКодомП === 'function') ? питанняКодомП(п) : String(п)),
      тексти_питань: (к.питання_жінці || []),
      /* Ч-7 (27.09.2026): скільком питанням шар ВІДПОВІВ текстом — з записів виклику, до
         сторожа П-3 (`лишеЛатиницеюП`). Це міряє код: чи кожне «код не знає» доїхало до
         моделі й чи вона на нього відповіла. Чи відповідь українська — міряє сам сторож. */
      /* РЯДОК 240: питання, яких ця картка шару вдруге не ставила — відповідь стоїть у пам'яті
         показу (їх поставила сусідня рука, що встигла першою); показ тепер кладе число в картку */
      питань_з_пам_яті: к.питання_з_пам_яті || 0,
      питань_від_шару: (к.мова_шару || []).filter(з => з.напрям === 'out_messages'
        && /code_unknowns/.test(з.де || '')).reduce((н, з) => н + Object.keys(з.вихід || {}).filter(к_ => /^питання\./.test(к_)).length
                                                             + ((з.чужою || []).filter(к_ => /^питання\./.test(к_)).length), 0)})),
    дом: [...document.querySelectorAll('#картки .картка')].map(к => ({текст: к.textContent.replace(/\s+/g, ' ').slice(0, 4000),
      /* МШ-1 (рядок 311): ПРОЗА картки — «Чому цей образ» (`.текст-образу`) і рядки «Як це
         носити» (`.к-текст > .задум > div`; блок «код не знає» має свій `.задум` усередині
         `details.питання-коду` і сюди не потрапляє). Чужомовні з них рахує САМ ПРОДУКТ своїм
         сторожем (`чужоюМовоюП`) — стенд не заводить власного правила мови. */
      проза_рядків: [...к.querySelectorAll('.текст-образу, .к-текст > .задум > div')]
        .filter(э => э.textContent.trim()).length,
      проза_чужою: [...к.querySelectorAll('.текст-образу, .к-текст > .задум > div')]
        .map(э => э.textContent.replace(/\s+/g, ' ').trim())
        .filter(т => т && typeof чужоюМовоюП === 'function' && чужоюМовоюП(т)),
      картинок: к.querySelectorAll('img').length, разом: /Разом/.test(к.textContent), кнопка_не_ця: /не ця/.test(к.textContent),
      /* блок «код не знає» (власник 20.09): згорнутий за замовчуванням, у ньому
         ВЕСЬ перелік. `питань_у_домі` — скільки рядків реально намальовано. */
      згорнуто: [...к.querySelectorAll('.питання-коду')].every(д => !д.open),
      підпис_питань: ((к.querySelector('.питання-коду summary') || {}).textContent || ''),
      питань_у_домі: к.querySelectorAll('.питання-коду .задум div').length,
      рядки_питань: [...к.querySelectorAll('.питання-коду .задум div')].map(р => р.textContent)})),
    діагноз: (ЗБ.діагноз || []), пул: (((typeof П !== 'undefined' && П) || {}).пул || null),
    розклад: (((typeof П !== 'undefined' && П) || {}).розклад || null), поломка: ЗБ.поломка, контроль: ЗБ.контроль }));
  console.log('\n2б. чотири картки за', ч(), '· розклад рук:', с2.розклад, '· пул:', с2.пул, '· поломка руки 2:', JSON.stringify(с2.поломка && с2.поломка.назва),
              '· контроль:', JSON.stringify(с2.контроль));
  for (const к of с2.картки) console.log('   рука', к.рука, JSON.stringify(к));
  await ЧАСИ.звіт(стор);
  ф('чотири картки, жодного збою', с2.картки.length === 4 && с2.картки.every(к => !к.збій), с2.картки.map(к => к.збій));
  /* П-7: у звіті власника — хто обрав схему, основу й гаму і чому (рядки «вибір палітри:») */
  const виборП7 = с2.діагноз.filter(д => /^palette · (choice|stylist_not_asked)/.test(д));
  console.log('   П-7 діагноз вибору палітри: ' + JSON.stringify(виборП7));
  /* ── ЩО КОД ПОЧУВ І НЕ ВЗЯВ — У ЗВІТІ ВЛАСНИКА (рядок 188) ────────────────
     Поле паспорта `не_взято_кодом` мусить доїхати в `ЗБ.діагноз`, бо саме звідти
     його читає звіт вердиктів. Інакше «код мовчки не взяв поле моделі» — а це те
     саме мовчання, яке рядок 188 і прибирає, лише з іншого боку. */
  if ((с1.не_взято || []).length)
    ф('що код почув від моделі й не взяв — рядком у звіті власника (' + с1.не_взято.length + ')',
      с1.не_взято.every(р => с2.діагноз.some(д => д.indexOf(String(р)) >= 0)),
      {не_взято: с1.не_взято, діагноз: с2.діагноз.filter(д => /^passport · /.test(д))});
  /* РЕМОНТ ПОВНОТИ — ЗАКОННА ІТЕРАЦІЯ (рядок 146). Заглушка пальта не бере, тож
     нижче +10 °C (сценарій «+5, дощ» або поломка «температура» руки 2, сід 8:
     +18 → +8,2 °C) драбина повноти справді відпрацьовує: ітерацій стає більше
     рівно на спроби ремонту, і лише коли діагноз руки їх називає. Щонайбільше
     дві — `реєстр.спроб_повноти`. На типовому шляху умова та сама, що доти. */
  const ремонтівПовноти = р => с2.діагноз.filter(д => д.startsWith('hand_' + р + ' · completeness_repair')).length;
  /* РУКИ 3–4: ДВА ВИКЛИКИ, І ДРУГИЙ — НЕ ІТЕРАЦІЯ (Т-8, 25.09.2026). Доти тут стояло
     `викликів === 1`. Тепер після відповіді руки йде ОДИН короткий виклик «випиши речі
     з опису»: перелік речей на картці дає модель, а не шаблони рядків над прозою.
     Логіка руки та сама — промпт руки байт у байт, `ітерацій` лишається 0, коду в руці
     як не було, так і нема; змінилось рівно число викликів, і саме тому число тут
     назване, а не послаблене до «≥ 1»: третій виклик у руці без коду був би вже іншою
     рукою. */
  ф('руки 1–2: дві ітерації + вибір + опис (ітерацій 3, викликів ≥ 4); руки 3–4: складання + перелік речей (2, ітерацій 0)',
    с2.картки.filter(к => к.рука <= '2').every(к => (к.ітерацій === 3
      || (к.ітерацій > 3 && к.ітерацій - 3 <= Math.min(2, ремонтівПовноти(к.рука)))) && к.викликів >= 4)
    && с2.картки.filter(к => к.рука >= '3').every(к => к.викликів === 2 && к.ітерацій === 0),
    с2.картки.map(к => [к.рука, к.ітерацій, к.викликів]));
  /* ── ПЕРЕЛІК РЕЧЕЙ І ПРОЗА ГОВОРЯТЬ ПРО ОДИН ОБРАЗ (Т-8, 25.09.2026) ─────────
     Звірка вище рахує ВИКЛИКИ; ця — їхній результат. Окремий виклик має сенс лише
     тоді, коли його відповідь про той самий образ, що й проза під нею: модель не
     вигадала речі, якої в тексті нема, а код не загубив жодної з названих. Ловить
     обидва боки поломки:
       · річ переліку, якої в прозі нема → модель (або заглушка) дописала своє;
       · названо N, а на картці менше → код губить речі, тобто повернувся дефект,
         заради якого Т-8 і робилась (2 з 7 на прозах 25.09).
     Слова назви шукаються в прозі окремо: назва на картці — перший відрізок рядка
     переліку («сумка через плече» з «сумка через плече, коньячна, шкіра»), а перепис
     мови міг переставити слова місцями. `названо → на картці` читається з того самого
     рядка звіту власника, який цей шлях і друкує, — іншого джерела правди тут нема. */
  const словаНазвиТ8 = н => String(н).toLowerCase().replace(/[^\p{L}\p{N}\s]/gu, ' ').split(/\s+/).filter(с => с.length >= 4);
  const прозаНесеТ8 = (н, п) => { const пн = String(п).toLowerCase();
    return словаНазвиТ8(н).every(с => пн.indexOf(с) >= 0); };
  const безПрозиТ8 = [];
  for (const к of с2.картки.filter(к => к.рука >= '3'))
    for (const н of (к.назви_до_шару || к.назви || [])) if (!прозаНесеТ8(н, к.проза)) безПрозиТ8.push([к.рука, н]);
  /* рядок 1452: слот, який модель позначила непотрібним (`worn` false), у діагнозі стоїть `not_needed=N` і на картку не йде,
     тож «названо» = «на картці» + «непотрібних» */
  const лічбаТ8 = с2.діагноз.map(д => /^hand_(\d) · items_source=separate_call · model_named=(\d+) · on_card=(\d+)(?: · not_needed=(\d+))?$/.exec(д)).filter(Boolean);
  ф('руки 3–4: кожна річ переліку названа в прозі, і жодна названа не загубилась',
    безПрозиТ8.length === 0 && лічбаТ8.length === 2 && лічбаТ8.every(м => +м[2] === +м[3] + +(м[4] || 0)),
    {речі_поза_прозою: безПрозиТ8, названо_на_картці: лічбаТ8.map(м => [м[1], м[2], м[3], м[4] || 0]),
     назви: с2.картки.filter(к => к.рука >= '3').map(к => [к.рука, к.назви])});
  /* РЯДОК 1452: заглушка переліку (NEPOTRIBNA=1) віддала слот колгот із `worn: false` — на картках рук 3–4 його нема, а діагноз його називає */
  if (process.env.NEPOTRIBNA)
    ф('руки 3–4: слот, позначений моделлю непотрібним (worn false), не малюється річчю і названий у діагнозі (рядок 1452)',
      лічбаТ8.length === 2 && лічбаТ8.every(м => +м[4] === 1)
      && с2.картки.filter(к => к.рука >= '3').every(к => !(к.назви || []).some(н => /колготки/.test(н))),
      {діагноз: лічбаТ8.map(м => [м[1], м[4] || 0]), назви: с2.картки.filter(к => к.рука >= '3').map(к => [к.рука, к.назви])});
  /* Доти тут стояло `к.фото === к.речей` — «на руках 1–2 кожна річ із фото». Рядок 118
     (21.09.2026) зробив це твердження неправдивим У ПРАВИЛЬНИЙ БІК: `bridge.показ` більше
     не підставляє логотип крамниці, коли власного знімка речі у фіді нема (1 405 речей із
     12 405 каталогу), і така річ іде аркою. Звірка не послаблена, а уточнена: фото має
     бути на КОЖНІЙ речі, у якої воно в каталозі є; порожнім лишається рівно те, що
     порожнє й у фіді (`фото_усі` тієї ж картки). Мовчазна втрата знімка, який у речі Є,
     падає так само, як падала доти. */
  ф('руки 1–2: речі з фото й цінами, окрім тих, у яких свого знімка в каталозі нема (арка); руки 3–4: речі без фото (Р-4 не вирішено — картки різняться)',
    с2.картки.filter(к => к.рука <= '2').every(к => к.речей >= 2 && к.фото + к.без_свого === к.речей) && с2.картки.filter(к => к.рука >= '3').every(к => к.фото === 0),
    с2.картки.map(к => [к.рука, к.речей, к.фото, к.без_свого]));
  const видимі = с2.дом.map(д => д.текст);
  ф('на жодній картці нема «#N·MM», hex чи кодів правил', видимі.every(т => !НОМЕР.test(т) && !HEX.test(т) && !КОД.test(т)),
    видимі.map(т => [(т.match(НОМЕР) || [])[0], (т.match(HEX) || [])[0], (т.match(КОД) || [])[0]]));
